targets.query:
from(bucket: "smart_home_db")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "DB")
  |> filter(fn: (r) => r._field == "measurement")
  |> last()
  |> map(fn: (r) => ({
      r with
      value_num: if r._value then 1 else 0
  }))
  |> keep(columns: ["_time", "value_num"])

